/**
 * Get Hiragana reading for a Japanese word.
 * Returns empty string if not found in offline dictionary.
 * 
 * @param {string} word
 * @returns {string} Hiragana reading
 */
export const getOfflineReading = (word) => {
  if (!word || typeof word !== 'string') return '';
  const clean = word.trim();
  if (WORD_READING_MAP[clean]) {
    return WORD_READING_MAP[clean];
  }
  // Try stripping common trailing particles (は, が, を, に, で, へ, と, も, から, まで, の)
  if (clean.length > 1) {
    const stripped = clean.replace(/([はがをにでへともからまでの])$/, '');
    if (WORD_READING_MAP[stripped]) {
      return WORD_READING_MAP[stripped];
    }
  }
  return '';
};

export default {
  WORD_READING_MAP,
  getOfflineReading
};
